-- Lernfeld:1 > Das Unternehmen und die eigene Rolle im Betrieb beschreiben > Das Unternehmen > Wettbewerb
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Binärfragen (8 Stück, 40%)
('00000000-0000-0000-0000-000000000000', 'Kann ein Unternehmen ohne Wettbewerb existieren?', 2, '[{"text": "Ja", "correct": true, "because": "Monopol möglich"}, {"text": "Nein", "correct": false, "because": "Wettbewerb oft vorhanden"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss unser Betrieb im Wettbewerb immer der Beste sein?', 2, '[{"text": "Nein", "correct": true, "because": "Überleben reicht"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist der Wettbewerb für unsere Preise relevant?', 2, '[{"text": "Ja", "correct": true, "because": "Marktdynamik beeinflusst"}, {"text": "Nein", "correct": false, "because": "Preise wettbewerbsabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Könnte unser Betrieb durch Wettbewerb Kunden verlieren?', 2, '[{"text": "Ja", "correct": true, "because": "Konkurrenz lockt"}, {"text": "Nein", "correct": false, "because": "Wettbewerbsrisiko"}]'),
('00000000-0000-0000-0000-000000000000', 'Sag mir nochmal: Beeinflusst der Wettbewerb unsere Qualität?', 2, '[{"text": "Ja", "correct": true, "because": "Druck zur Verbesserung"}, {"text": "Nein", "correct": false, "because": "Qualität wettbewerbsrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann der Wettbewerb unseren Betrieb schließen?', 2, '[{"text": "Ja", "correct": true, "because": "Starke Konkurrenz gefährdet"}, {"text": "Nein", "correct": false, "because": "Mögliches Risiko"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist der Wettbewerb nur lokal relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Globaler Wettbewerb möglich"}, {"text": "Ja", "correct": false, "because": "Überregional einflussreich"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss unser Betrieb den Wettbewerb beobachten?', 2, '[{"text": "Ja", "correct": true, "because": "Strategisch wichtig"}, {"text": "Nein", "correct": false, "because": "Wettbewerbsanalyse nötig"}]'),
-- Single-Choice-Fragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel im Wettbewerb für unseren Betrieb?', 2, '[{"text": "Kunden gewinnen", "correct": true, "because": "Wettbewerbsvorteil"}, {"text": "Urlaub planen", "correct": false, "because": "Irrelevant"}, {"text": "Steuern sparen", "correct": false, "because": "Nebenaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Meine Chefin sagt, der Wettbewerb wird härter. Was bedeutet das?', 3, '[{"text": "Mehr Konkurrenz", "correct": true, "because": "Marktdruck steigt"}, {"text": "Weniger Arbeit", "correct": false, "because": "Unlogisch"}, {"text": "Höhere Steuern", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor beeinflusst den Wettbewerb am meisten?', 2, '[{"text": "Preise", "correct": true, "because": "Kundendeterminante"}, {"text": "Wetter", "correct": false, "because": "Geringer Einfluss"}, {"text": "Farben", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Der Abteilungsleiter fragt, wie wir im Wettbewerb bestehen. Was sage ich?', 3, '[{"text": "Bessere Qualität", "correct": true, "because": "Wettbewerbsvorteil"}, {"text": "Weniger arbeiten", "correct": false, "because": "Unlogisch"}, {"text": "Urlaub nehmen", "correct": false, "because": "Kein Bezug"}]'),
-- Multiple-Choice-Fragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren spielen im Wettbewerb eine Rolle?', 4, '[{"text": "Preise", "correct": true, "because": "Kundenentscheidend"}, {"text": "Qualität", "correct": true, "because": "Differenzierung"}, {"text": "Service", "correct": true, "because": "Kundenzufriedenheit"}, {"text": "Bürofarbe", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was könnte unser Betrieb im Wettbewerb stärken?', 3, '[{"text": "Niedrigere Preise", "correct": true, "because": "Attraktivität"}, {"text": "Bessere Produkte", "correct": true, "because": "Qualität"}, {"text": "Schneller Service", "correct": true, "because": "Kundenvorteil"}, {"text": "Weniger Mitarbeiter", "correct": false, "because": "Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Wir verlieren Kunden an die Konkurrenz. Was beeinflusst den Wettbewerb?', 3, '[{"text": "Preisunterschiede", "correct": true, "because": "Kundenwahl"}, {"text": "Qualitätsmängel", "correct": true, "because": "Wettbewerbsnachteil"}, {"text": "Marketing", "correct": true, "because": "Sichtbarkeit"}, {"text": "Wetter", "correct": false, "because": "Geringer Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken bringt der Wettbewerb für unseren Betrieb?', 4, '[{"text": "Kundenverlust", "correct": true, "because": "Konkurrenz"}, {"text": "Preisdruck", "correct": true, "because": "Marktdynamik"}, {"text": "Innovationszwang", "correct": true, "because": "Wettbewerbsvorteil"}, {"text": "Mehr Urlaub", "correct": false, "because": "Kein Risiko"}]'),
-- Kombinationsfragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Wettbewerb beeinflusst unsere Preise. b) Er ist für uns irrelevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Preise ja, irrelevant nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Wettbewerb kann Kunden kosten. b) Er zwingt uns, die Besten zu sein.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kundenverlust ja, Beste nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Wettbewerb fördert Qualität. b) Er ist nur lokal wichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Qualität ja, lokal nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Wettbewerb bringt Preisdruck. b) Er hat keinen Einfluss auf uns.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Preisdruck ja, Einfluss ja"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

